      process.stdout.write(`${JSON.stringify(createManifest(root, paths))}\n`);
      return 0;
    }
    if (command === 'verify') {
      if (rest.length !== 2) throw Error(CLI_USAGE);
      const [root, manifestFile] = rest;
      let text;
      try { text = fs.readFileSync(manifestFile, 'utf8'); }
      catch (error) { throw Error(`unable to read manifest file: ${error.message}`); }
      let manifest;
      try { manifest = JSON.parse(text.replace(/^\uFEFF/, '')); }
      catch { throw Error('manifest file is not valid JSON'); }
      const report = verifyManifest(root, manifest);
      process.stdout.write(`${JSON.stringify(report)}\n`);
      return report.ok ? 0 : 1;
    }
    throw Error(CLI_USAGE);
  } catch (error) {
