import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import * as snapshot from '../snapshot.js';

const SCRIPT = fileURLToPath(new URL('../snapshot.js', import.meta.url));
const sha256 = value => crypto.createHash('sha256').update(value).digest('hex');
const HEX = sha256('seed');

function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-verify-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function write(root, relative, content, mode) {
  const file = path.join(root, ...relative.split('/'));
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  if (mode !== undefined) fs.chmodSync(file, mode);
  return file;
}
function entry(relative, content, mode) {
  return { path: relative, sha256: sha256(content), size: Buffer.byteLength(content), mode };
}
function runCli(args) {
  return spawnSync(process.execPath, [SCRIPT, ...args], { encoding: 'utf8' });
}
function reportOf(unchanged = [], changed = [], missing = [], unsafe = []) {
  return { ok: changed.length === 0 && missing.length === 0 && unsafe.length === 0, unchanged, changed, missing, unsafe };
}

test('verify reports unchanged, content-only, mode-only and both', t => {
  const root = fixture(t);
  write(root, 'a.txt', 'abc', 0o644);
  const manifest = { version: 1, files: [entry('a.txt', 'abc', 0o644)] };
  assert.deepEqual(snapshot.verifyManifest(root, manifest), reportOf(['a.txt']));
  // content only
  fs.writeFileSync(path.join(root, 'a.txt'), 'abcd');
  assert.deepEqual(snapshot.verifyManifest(root, manifest), reportOf([], [{ path: 'a.txt', reasons: ['content'] }]));
  // mode only
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.chmodSync(path.join(root, 'a.txt'), 0o600);
  assert.deepEqual(snapshot.verifyManifest(root, manifest), reportOf([], [{ path: 'a.txt', reasons: ['mode'] }]));
  // content and mode, order fixed
  fs.writeFileSync(path.join(root, 'a.txt'), 'xyz');
  fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  assert.deepEqual(snapshot.verifyManifest(root, manifest), reportOf([], [{ path: 'a.txt', reasons: ['content', 'mode'] }]));
  // size mismatch with matching hash still means content
  fs.writeFileSync(path.join(root, 'a.txt'), 'xyz');
  const lying = { version: 1, files: [{ path: 'a.txt', sha256: sha256('xyz'), size: 99, mode: 0o640 }] };
  assert.deepEqual(snapshot.verifyManifest(root, lying), reportOf([], [{ path: 'a.txt', reasons: ['content'] }]));
  // empty manifest
  assert.deepEqual(snapshot.verifyManifest(root, { version: 1, files: [] }), reportOf());
});

test('verify classifies missing and unsafe components', t => {
  const root = fixture(t);
  fs.mkdirSync(path.join(root, 'dir'));
  write(root, 'dir/file.txt', 'x', 0o644);
  write(root, 'plain.txt', 'y', 0o644);
  fs.symlinkSync(path.join(root, 'plain.txt'), path.join(root, 'link.txt'));
  fs.symlinkSync(path.join(root, 'dir'), path.join(root, 'linkdir'));
  const files = [
    entry('plain.txt/inner', 'q', 0o644),
    entry('gone.txt', 'g', 0o644),
    entry('linkdir/file.txt', 'x', 0o644),
    entry('dir', 'q', 0o644),
    entry('link.txt', 'y', 0o644),
    entry('dir/file.txt', 'x', 0o644),
    entry('dir/gone.txt', 'g', 0o644),
  ];
  assert.deepEqual(snapshot.verifyManifest(root, { version: 1, files }),
    reportOf(['dir/file.txt'], [], ['dir/gone.txt', 'gone.txt'], ['dir', 'link.txt', 'linkdir/file.txt', 'plain.txt/inner']));
  // broken symlink is existing-but-symlink, so unsafe, not missing
  fs.symlinkSync(path.join(root, 'nowhere'), path.join(root, 'broken'));
  assert.deepEqual(snapshot.verifyManifest(root, { version: 1, files: [entry('broken', 'q', 0o644)] }).unsafe, ['broken']);
});

test('verify sorts output by JavaScript string order and does not mutate inputs', t => {
  const root = fixture(t);
  write(root, 'b.txt', '1', 0o644);
  write(root, 'A.txt', '2', 0o644);
  const files = [entry('b.txt', '1', 0o644), entry('A.txt', '2', 0o644)];
  const manifest = { version: 1, files };
  const before = JSON.parse(JSON.stringify(manifest));
  assert.deepEqual(snapshot.verifyManifest(root, manifest), reportOf(['A.txt', 'b.txt']));
  assert.deepEqual(manifest, before);
  const paths = ['b.txt', 'A.txt'];
  const manifest2 = snapshot.createManifest(root, paths);
  assert.deepEqual(paths, ['b.txt', 'A.txt']);
  assert.deepEqual(manifest2.files.map(file => file.path), ['A.txt', 'b.txt']);
});

test('verify supports spaces, tabs, newlines and unicode filenames', t => {
  const root = fixture(t);
  const name = 'we ird\tname\nh\u00e9ll\u00f8.txt';
  write(root, name, 'data', 0o644);
  const manifest = snapshot.createManifest(root, [name]);
  assert.equal(snapshot.verifyManifest(root, manifest).ok, true);
  assert.deepEqual(snapshot.verifyManifest(root, manifest).unchanged, [name]);
});

test('verifyManifest rejects invalid manifests without partial reports', t => {
  const root = fixture(t);
  write(root, 'ok.txt', 'x', 0o644);
  const good = entry('ok.txt', 'x', 0o644);
  const invalid = [
    null, undefined, 42, 'manifest', [],
    { version: 2, files: [] }, { version: 1.5, files: [] }, { version: '1', files: [] }, { version: true, files: [] }, { files: [] },
    { version: 1, files: 'nope' }, { version: 1, files: null },
    { version: 1, files: [null] }, { version: 1, files: [42] }, { version: 1, files: ['s'] }, { version: 1, files: [[]] },
    { version: 1, files: [good, good] },
    { version: 1, files: [{}], },
    { version: 1, files: [{ path: '/abs', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a\\b', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a\0b', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a//b', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a/./b', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a/../b', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: '', sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 42, sha256: HEX, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX.toUpperCase(), size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX.slice(0, 63), size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: `g${'a'.repeat(63)}`, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: 123, size: 1, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: -1, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 1.5, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: NaN, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 2 ** 53, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: '1', mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, mode: 0 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 1, mode: -1 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 1, mode: 512 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 1, mode: 0.5 }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 1, mode: '644' }] },
    { version: 1, files: [{ path: 'a', sha256: HEX, size: 1, mode: true }] },
    // invalid entry alongside a valid one: still throws, no partial report
    { version: 1, files: [good, { path: 'a', sha256: HEX, size: -1, mode: 0 }] },
  ];
  for (const manifest of invalid) {
    assert.throws(() => snapshot.verifyManifest(root, manifest), Error, JSON.stringify(manifest));
  }
  // boundary values are valid; unknown fields are ignored
  const boundary = { version: 1, files: [{ path: 'ok.txt', sha256: sha256('x'), size: 1, mode: 0o777, notes: 'ignored' }] };
  assert.deepEqual(snapshot.verifyManifest(root, boundary).changed, [{ path: 'ok.txt', reasons: ['mode'] }]);
  const zero = { version: 1, files: [{ path: 'ok.txt', sha256: sha256('x'), size: 1, mode: 0 }] };
  assert.deepEqual(snapshot.verifyManifest(root, zero).changed, [{ path: 'ok.txt', reasons: ['mode'] }]);
});

test('verifyManifest rejects invalid roots', t => {
  const root = fixture(t);
  const manifest = { version: 1, files: [] };
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'nope'), manifest), Error);
  assert.throws(() => snapshot.verifyManifest(null, manifest), Error);
  assert.throws(() => snapshot.verifyManifest(42, manifest), Error);
  const file = write(root, 'plain.txt', 'y');
  assert.throws(() => snapshot.verifyManifest(file, manifest), Error);
  fs.symlinkSync(root, path.join(root, 'rootlink'));
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'rootlink'), manifest), Error);
});

test('createManifest preserves existing behavior', t => {
  const root = fixture(t);
  assert.deepEqual(snapshot.createManifest(root, []), { version: 1, files: [] });
  write(root, 'a.txt', 'abc', 0o640);
  fs.mkdirSync(path.join(root, 'd'));
  assert.throws(() => snapshot.createManifest(root, ['d']), Error);
  assert.throws(() => snapshot.createManifest(root, ['nope']), Error);
  assert.throws(() => snapshot.createManifest(root, ['a.txt', 'a.txt']), Error);
  assert.throws(() => snapshot.createManifest(root, 'not-an-array'), Error);
  assert.throws(() => snapshot.createManifest(path.join(root, 'a.txt'), []), Error);
});

test('CLI create and verify exit codes and output', t => {
  const root = fixture(t);
  write(root, 'a.txt', 'abc', 0o640);
  const created = runCli(['create', root, 'a.txt']);
  assert.equal(created.status, 0);
  assert.equal(created.stderr, '');
  const manifest = { version: 1, files: [{ path: 'a.txt', sha256: sha256('abc'), size: 3, mode: 0o640 }] };
  assert.deepEqual(JSON.parse(created.stdout), manifest);
  assert.equal(created.stdout, JSON.stringify(manifest) + '\n');
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, JSON.stringify(manifest));
  const ok = runCli(['verify', root, manifestFile]);
  assert.equal(ok.status, 0);
  assert.equal(ok.stderr, '');
  assert.equal(ok.stdout, JSON.stringify(reportOf(['a.txt'])) + '\n');
  // drift exits 1, same single-JSON-line stdout, no stderr
  fs.writeFileSync(path.join(root, 'a.txt'), 'changed');
  const drift = runCli(['verify', root, manifestFile]);
  assert.equal(drift.status, 1);
  assert.equal(drift.stderr, '');
  assert.equal(drift.stdout, JSON.stringify(reportOf([], [{ path: 'a.txt', reasons: ['content'] }])) + '\n');
  // empty selection
  const empty = runCli(['create', root]);
  assert.equal(empty.status, 0);
  assert.equal(empty.stdout, JSON.stringify({ version: 1, files: [] }) + '\n');
});

test('CLI errors exit 2 with nonempty stderr and no stdout', t => {
  const root = fixture(t);
  write(root, 'a.txt', 'abc', 0o640);
  const badJsonFile = path.join(root, 'bad.json');
  fs.writeFileSync(badJsonFile, '{oops');
  const badManifestFile = path.join(root, 'bad-manifest.json');
  fs.writeFileSync(badManifestFile, JSON.stringify({ version: 2, files: [] }));
  fs.symlinkSync(root, path.join(root, 'rootlink'));
  const cases = [
    [],
    ['bogus', root],
    ['create'],
    ['create', root, 'nope.txt'],
    ['create', root, 'a.txt', 'a.txt'],
    ['create', root, '../outside'],
    ['create', path.join(root, 'a.txt')],
    ['verify', root],
    ['verify', root, 'm.json', 'extra'],
    ['verify', root, path.join(root, 'missing-manifest.json')],
    ['verify', root, badJsonFile],
    ['verify', root, badManifestFile],
    ['verify', path.join(root, 'no-such-root'), badManifestFile],
    ['verify', path.join(root, 'a.txt'), badManifestFile],
    ['verify', path.join(root, 'rootlink'), badManifestFile],
  ];
  for (const args of cases) {
    const result = runCli(args);
    assert.equal(result.status, 2, JSON.stringify(args));
    assert.equal(result.stdout, '', JSON.stringify(args));
    assert.ok(result.stderr.length > 0, JSON.stringify(args));
  }
});

